  "supplier.farmer": "Granjero Petróvich",
  "supplier.farmer.hello": "¡Pan fresco, manzanas y papas de esta mañana! Llévatelos, no te vas a arrepentir.",
  "supplier.dairy": "Zinaída, MolTorg",
  "supplier.dairy.hello": "Leche según la factura. Los precios son fijos… casi.",
  "supplier.butcher": "Carnicero Stepánich",
  "supplier.butcher.hello": "Cortes de esta mañana, todavía tibios. Directo al refrigerador, ¿oíste?",
  "who.grandma": "Abuela",
  "who.valya": "Valentina, vecina",
  "who.marat": "Marat, chef del Café Acogedor",
  "who.eduard": "Eduard, director de MegaMart",
  "who.inspector": "Belova, inspección sanitaria",
  "story.chapter": "Capítulo {n}: {title}",
  "story.next": "Seguir",
  "story.reward": "Premio: {reward}",
  "story.goalLine": "📖 {title}: {goal}",
  "story.free": "📖 Juego libre: sigue haciendo crecer tu tienda",
  "story.ch1.title": "La herencia",
  "story.ch1.goal": "paga la deuda de la abuela (faltan {n} 💰)",
  "story.ch1.intro1": "¡Hola! Soy la abuela. Me fui al campo con mis hermanas y te dejo mi quiosco de la esquina.",
  "story.ch1.intro2": "Te mando mi cuaderno por carta: ahí está todo sobre lo que les debo a los vecinos. Devuélveselo, por favor: es lo correcto.",
  "story.ch1.intro3": "¡Ay, ahora atiendes tú! Soy yo, Valentina, la amiga de tu abuela, ¿te acuerdas? ¡Vendré por pan todos los días!",
  "story.ch1.outro1": "¡Me enteré de que ya pagaste toda la deuda! Tu abuela llamó: está orgullosa.",
  "story.ch1.outro2": "Por cierto, el otro día vino Marat, el cocinero del Café Acogedor. Busca dónde comprar productos…",
  "story.ch2.title": "Gente de confianza",
  "story.ch2.goal": "completa 2 pedidos ({n}/2) y contrata a tu primer empleado ({staff})",
  "story.ch2.intro1": "¡Buenas! Soy Marat, chef del Café Acogedor. Valentina dice que sus precios son justos.",
  "story.ch2.intro2": "De vez en cuando haré pedidos para la noche. No me falle: siempre tengo el local lleno.",
  "story.ch2.outro1": "Usted cumple su palabra. ¡Lo voy a recomendar a todos mis conocidos!",
  "story.ch3.title": "El rival",
  "story.ch3.goal": "crece hasta minimercado con valoración 4★ (ahora {r}★). MegaMart se lleva a algunos clientes",
  "story.ch3.intro1": "Soy Eduard, director de MegaMart. Vamos a abrir justo enfrente.",
  "story.ch3.intro2": "Tenemos cuarenta cajas y descuentos todos los días. Un consejo: venda el quiosco mientras todavía valga algo.",
  "story.ch3.intro3": "¡No le hagas caso! Los clientes de siempre no se irán… Aunque algunos sí irán a echar un vistazo, claro.",
  "story.ch3.outro1": "¿Un minimercado? ¿Y con mejor valoración que la nuestra? Vaya, vaya…",
  "story.ch4.title": "La inspección",
  "story.ch4.goal": "pasa 2 inspecciones ({n}/2)",
  "story.ch4.intro1": "Belova, inspección sanitaria. Recibimos una queja sobre usted.",
  "story.ch4.intro2": "Vendré más seguido. Basura, baño sucio, productos defectuosos, refrigerador tibio: lo veré todo.",
  "story.ch4.intro3": "¡Fue Eduard quien se quejó, te lo aseguro!",
  "story.ch4.outro1": "Una tienda modelo. Eso pondré en mi informe.",
  "story.ch4.outro2": "¡Vaya!… Y yo refunfuñando contra él toda la semana. Le llevaré una empanadita para hacer las paces.",
  "story.ch5.title": "Gran almacén",
  "story.ch5.goal": "crece hasta gran almacén",
  "story.ch5.intro1": "¡Te llamo desde el campo! Me dijeron que Edik va a ir a verte. Escúchalo, ¿sí? Era un buen chico.",
  "story.ch5.intro2": "Traje lo que debo. Por el pan y la leche: treinta años, con intereses. Por favor, acéptelo.",
  "story.ch5.outro1": "Aquí estoy. Y te soy sincera: no me fui por el campo. Necesitabas a alguien por quien levantarte a las seis.",
  "story.ch5.outro2": "Ahora todo el barrio compra aquí. Y Eduard, imagínate, amenaza con abrir un quiosco al lado, «para no aburrirse».",
  "story.ch5.outro3": "La última página todavía no te la voy a enseñar. Al otro lado del puente aún está oscuro… Ya le llegará su turno.",
  "client.chef": "Marat, Café Acogedor",
  "client.chef.ask": "Necesito {qty} × {product} para la noche: pago {pay} 💰 por unidad.",
  "client.school": "Comedor escolar",
  "client.school.ask": "Pasaremos por {qty} × {product} en la noche, a {pay} 💰 cada uno.",
  "client.valya": "Valentina",
