  "tip.new": "💡 Nuevo",
  "tip.ok": "Entendido",
  "tip.weekly.title": "Retos semanales",
  "tip.weekly.text": "Tres metas para la semana: el progreso se suma día a día. Cada una da su premio en cuanto la cumples.",
  "tip.fair.title": "Feria",
  "tip.fair.text": "Una vez al mes hay feria en la entrada: un puesto vende mercancía del almacén un 25% más cara, sin pasar por caja. ¡Llena el almacén!",
  "tip.loyalty.title": "Tarjeta de cliente",
  "tip.loyalty.text": "Con la tarjeta, los clientes aceptan precios un 6% más altos: puedes subir un poco los precios. Y quien se va sin comprar baja menos la valoración.",
  "tip.delivery.title": "Envío a domicilio",
  "tip.delivery.text": "Durante el día suena el teléfono de la caja y abajo aparece una tarjeta de pedido. Toca “Aceptar”: se arma el pedido, el repartidor lo entrega y trae el dinero, y si es rápido, hay propina. Si no contestas en 15 segundos, baja la valoración de los envíos y llamarán menos.",
  "tip.register2.title": "Caja nueva",
  "tip.register2.text": "Ahora tienes más de una caja. La primera es tuya, y cada caja nueva necesita su propio cajero (pestaña “Personal”); si no, queda cerrada. La fila va a la caja libre.",
  "tip.oven.title": "Panadería",
  "tip.oven.text": "Abrió una panadería en el anexo. Contrata un panadero en la pestaña “Personal”: él hornea el pan y lo lleva a los estantes. Mientras huela a pan, se vende el doble.",
  "tip.coffee.title": "Cafetería",
  "tip.coffee.text": "Abrió una cafetería en el anexo. Contrata un barista en la pestaña “Personal” y vigila los granos y los vasos en la pestaña “Rincones”: con lluvia se vende más café.",
  "tip.ownerTill.title": "La caja es tuya",
  "tip.ownerTill.text": "La primera caja la atiendes tú. Cobra tocando la caja o la calle debajo de la tienda: es más cómodo para el pulgar. Los cajeros atienden la segunda caja y las siguientes, y el cajero de relevo (desde la “Tiendita”) se queda con la tuya para siempre; entonces tus toques lo apuran.",
  "tip.broke.title": "Caja vacía",
  "tip.broke.text": "Sin dinero y con los estantes vacíos no habrá ventas. El banco te presta para comprar mercancía: pestaña “Crecer” → “Banco”. Lo pagas en partes junto con las facturas.",
  "tip.alone.title": "Solo no puedes",
  "tip.alone.text": "La tienda creció, pero la caja, los estantes y el almacén dependen de ti: los clientes se van y la valoración no sube. Contrata ayuda en la pestaña “Personal”: el reponedor llena los estantes, el limpiador limpia y un cajero atiende la segunda caja.",
  "tip.nightShift.title": "Turno de noche",
  "tip.nightShift.text": "Por la tarde puedes trabajar 45 segundos más: viene menos gente, pero nadie se queja de los precios.",
