  "tour.title": "La abuela te muestra la tienda · {n}/{total}",
  "tour.next": "Siguiente",
  "tour.skip": "Saltar",
  "tour.done": "¡Empecemos!",
  "tour.replay": "Tour de la abuela",
  "tour.replayNote": "La abuela te vuelve a mostrar dónde está todo",
  "tour.hello": "¡Hola, cariño! Antes de irme, déjame mostrarte cómo funciona todo aquí. ¡Es rapidito!",
  "tour.top": "Arriba ves qué día es y cuánto dinero tienes. Por la mañana te preparas, de día vendes y por la noche cuentas los ingresos.",
  "tour.today": "Aquí está lo importante de hoy: qué hacer por la mañana, el clima, cuántos clientes vendrán y cuándo toca pagar el alquiler y la luz.",
  "tour.buy": "“Compras”: aquí consigues mercancía. Toca “Comprar lo necesario”: yo calculo lo que falta y compro donde sea más barato. Con el tiempo los proveedores te hacen descuento solos, sin regatear.",
  "tour.warehouse": "“Sala”: arriba está el almacén, lo que no cupo en los estantes. Por la mañana se acomoda solo en los lugares libres, y lo que está por echarse a perder conviene rebajarlo.",
  "tour.shelves": "Más abajo en la “Sala” están tus estantes. Toca uno para mejorarlo, repararlo o venderlo. Aquí también compras nuevos. Los precios están en “Compras”.",
  "tour.extras": "“Rincones”: dulces junto a la caja, café, tu propio horno y un gatito. Para cuando la tienda crezca.",
  "tour.staff": "“Personal”: tus ayudantes. La primera caja siempre la atiendes tú; con el tiempo, el reponedor, el limpiador, el guardia y los cajeros de las cajas nuevas se encargarán del resto.",
  "tour.store": "“Crecer”: ampliar el local, cajas, equipamiento, publicidad, facturas y mi deuda con los vecinos. Los logros y la configuración están bajo la copa 🏆 de arriba.",
  "tour.open": "Cuando estés listo, toca “Abrir la tienda”. Los clientes toman cosas de los estantes y van a la caja: toca la caja o la calle de abajo para cobrarles.",
  // Apprentice (game/apprentice.ts).
