  "appr.offer.note": "Cada mañana lo pones en la caja, el almacén o la sala: lo que enseñas es lo que llega a ser. Beca de {n} 💰 por día de trabajo. En cuatro semanas abrirá su propia tienda: amiga o rival, según cómo le enseñes.",
