  "popup.apprTip": "+{n} 💰 por la ayuda",
  "tip.appr.title": "Aprendiz",
  "tip.appr.text": "Cada mañana, en la pestaña “Personal”, decide dónde trabaja hoy tu aprendiz: caja, almacén o sala. Lo que enseñas es lo que llega a ser. Paga la beca, elógialo y dale un día libre a la semana: en cuatro semanas tendrás un amigo con tienda al lado.",
  "tour.hall": "Si un estante está vacío, tócalo para traer mercancía del almacén. Limpia la basura y los charcos, y saca el cesto. Por la noche verás cuánto ganaste. ¡Suerte, cariño!",
