  "bigday.caption": "📺 Última hora",
  "bigday.anchor": "Alina, Noticias de la Ciudad",
  "bigday.ok": "¡Entendido, a trabajar!",
  "bigday.summary": "Día especial",
  "bigday.heatwave.title": "Calor récord",
  "bigday.heatwave.news": "¡Última hora! Una ola de calor récord: 41 °C a la sombra. Los médicos piden no salir a la calle hasta la tarde si no es necesario.",
  "bigday.heatwave.hint": "Hoy vendrán muchos menos clientes. Los que vengan buscarán agua, jugo y helado.",
  "bigday.frost.title": "Frío extremo",
  "bigday.frost.news": "¡Atención! Heladas de hasta −35 °C. Las escuelas están cerradas y se pide a los vecinos quedarse en casa.",
  "bigday.frost.hint": "Hoy vendrán pocos clientes. Querrán algo que llene: carne, pelmeni, papas y pan.",
  "bigday.flood.title": "Inundación",
  "bigday.flood.news": "¡Última hora! Tras las lluvias el río se desbordó y las calles están inundadas. Los rescatistas piden no salir si no es urgente.",
  "bigday.flood.hint": "Hoy vendrán pocos clientes. Necesitan agua, pan y productos de limpieza.",
  "bigday.quake.title": "Terremoto",
  "bigday.quake.news": "¡Atención! Los sismólogos registran temblores. Sin pánico: aléjense de estantes altos y ventanas.",
  "bigday.quake.hint": "Hoy vendrán pocos clientes, y con los temblores parte de la mercancía se caerá de los estantes y se romperá.",
  "bigday.carnival.title": "¡Carnaval!",
  "bigday.carnival.news": "¡Buenas noticias! Hoy pasa por nuestra calle un carnaval de verano: bailarines con plumas, tambores y carrozas, ¡como en Río de Janeiro!",
  "bigday.carnival.hint": "¡Habrá el doble de gente! Todos tendrán hambre y sed: agua, jugos, helado. No dejes vaciar los estantes.",
  "bigday.parade.title": "Desfile de bandas",
  "bigday.parade.news": "¡Hoy es el Día de la Ciudad! Por nuestra calle desfilan bandas de música, y detrás, los vecinos con banderitas y globos.",
  "bigday.parade.hint": "Habrá casi el doble de gente. Se venderán bien las flores, los jugos y el agua.",
  "popup.quake": "¡Temblor! Se rompió: {n}",
  "rare.queen": "Reina",
  "rare.pirate": "Pirata",
  "rare.clown": "Payaso",
  "rare.knight": "Caballero",
  "rare.alien": "Alienígena",
  "rare.magician": "Mago",
  "rare.viking": "Vikingo",
  "rare.superhero": "Superhéroe",
  "rare.ballerina": "Bailarina",
  "rare.ninja": "Ninja",
  "bigday.blackout.title": "Apagón",
  "bigday.blackout.news": "¡Última hora! Una avería en la subestación dejó a todo el barrio sin luz hasta el mediodía. Los técnicos ya están trabajando.",
  "bigday.blackout.hint": "Medio día sin luz: la caja cobra a mano y más lento, y los refrigeradores se calientan: lo que tienen envejece un día. Algo menos de clientes.",
  "bigday.filming.title": "¡Están filmando!",
  "bigday.filming.news": "La noticia del día: ¡justo frente a tu tienda se filma una escena de una nueva película! Estrellas, cámaras y multitudes de curiosos.",
  "bigday.filming.hint": "Muchos curiosos con ganas de beber y picar algo. Y la tienda saldrá en pantalla: mañana, publicidad gratis.",
  "bigday.marathon.title": "Maratón",
  "bigday.marathon.news": "¡Hoy es el maratón de la ciudad! Miles de corredores pasarán frente a tu tienda.",
  "bigday.marathon.hint": "Habrá una vez y media más gente. Corredores y aficionados arrasarán con el agua y los jugos.",
  "bigday.tourbus.title": "Bus de turistas",
  "bigday.tourbus.news": "¡Llegan turistas! Un autobús turístico parará justo frente a tu tienda.",
  "bigday.tourbus.hint": "Al mediodía bajarán del autobús {n} turistas a la vez: la caja no dará abasto. Les encantan el helado, el agua y los dulces.",
  "bigday.starfall.title": "Lluvia de estrellas",
  "bigday.starfall.news": "¡Esta noche, la lluvia de estrellas más brillante del año! Los astrónomos recomiendan salir y pedir un deseo.",
  "bigday.starfall.hint": "Por la noche toda la ciudad estará en la calle: con turno de noche, tendrás el doble de clientes nocturnos.",
  "bigday.pigeons.title": "Invasión de palomas",
  "bigday.pigeons.news": "Noticia curiosa: enormes bandadas de palomas llegaron a la ciudad. ¡Las aves se meten en tiendas y cafés!",
  "bigday.pigeons.hint": "Las palomas entrarán a la sala y asustarán a los clientes. Toca un ave para echarla.",
  "bigday.roadworks.title": "Obras viales",
  "bigday.roadworks.news": "¡Atención! Empiezan obras en la calle frente a tu tienda. Durarán {n} días.",
  "bigday.roadworks.hint": "Mientras excavan vienen menos clientes, pero los obreros con casco vienen a almorzar: pan, empanadas, pelmeni, agua.",
  "bigday.sanitary.title": "Inspección sanitaria",
  "bigday.sanitary.news": "¡Última hora! Sanidad hace inspecciones sorpresa en todas las tiendas del barrio.",
  "bigday.sanitary.hint": "Hoy vendrá un inspector. Recoge la basura y los charcos, tira lo vencido: la suciedad se multa.",
  "bigday.wedding.title": "Boda al lado",
  "bigday.wedding.news": "Buenas noticias: ¡hoy hay una boda en el café de al lado! Los novios te encargaron comida para la fiesta de la noche.",
  "bigday.wedding.hint": "Por la noche recogerán el pedido: {order}. Pagan más de lo normal, y si el pedido está completo, también sube tu valoración.",
  "bigday.epidemic.title": "Enfermedad peligrosa",
  "bigday.epidemic.news": "¡Atención! Hay un brote de una enfermedad peligrosa en la ciudad. Los médicos piden usar mascarilla y salir de casa lo menos posible.",
  "bigday.epidemic.hint": "Durante {n} días vendrán menos clientes, pero cada uno se abastece: jabón, productos de limpieza, agua, pelmeni y papas.",
  "bigday.dayOf": "{icon} {title}: día {n} de {of}",
