  "giant.build.news": "Noticias del barrio: ¡la cadena nacional Giant empezó a construir un enorme hipermercado justo frente a tu tienda! Abrirá en {n} días.",
  "giant.build.hint": "🕴️ Eduard: «Sé cómo hacen las cuentas. Mantén la valoración en 4.5★, pon publicidad, crea una tarjeta de cliente y hornea tu propio pan, y los tuyos no se irán a ningún lado».",
  "giant.battle.news": "¡Abrió Giant! Descuentos, globos y filas en el estacionamiento. Medio barrio fue a ver qué hay.",
  "giant.battle.hint": "La batalla por los clientes dura {n} días. Gana {target} 💰 y mantén tu valoración en {r}★ o más. Si lo logras, Giant cerrará.",
  "giant.won.news": "¡Sensacional! El hipermercado Giant cierra: el barrio eligió la tiendita acogedora de al lado. El director de la cadena admitió la derrota.",
  "giant.won.hint": "¡Venciste a Giant! Premio de +{reward} 💰 y +0.5★, y la fama en el barrio te da +{fame}% de clientes para siempre.",
  "giant.lost.news": "Giant resistió: en dos semanas se llevó a muchos clientes. Pero la cadena no está contenta con los ingresos y promete una nueva batalla por el barrio.",
  "giant.lost.hint": "Ganaste {revenue} de {target} 💰. En {n} días habrá revancha: prepárate mejor.",
