  "staffEvent.title": "👥 Personal: {name}, {role}",
  "staffEvent.wedding.text": "“Jefe, ¡se casa mi hermana! ¿Puedo ir mañana? Mi turno queda cubierto, de verdad.” Si dices que sí, volverá con ánimo y trabajará más rápido unos días.",
  "staffEvent.wedding.yes": "Dar el día libre",
  "staffEvent.wedding.no": "No, hay trabajo",
  "staffEvent.course.text": "“Hay un curso para vendedores: {n} 💰. Aprendería a trabajar más rápido.” Si lo pagas, su habilidad sube.",
  "staffEvent.course.yes": "Pagar el curso (−{n} 💰)",
  "staffEvent.course.no": "Ahora no",
  "staffEvent.advance.text": "“¿Me puede adelantar {n} 💰? Mi hijo necesita útiles para la escuela.” Si se lo das, se esforzará.",
  "staffEvent.advance.yes": "Adelantar (−{n} 💰)",
  "staffEvent.advance.no": "Que espere al sueldo",
  "staffEvent.quarrel.text": "{name} y {name2} se pelearon por los horarios y no se hablan. ¿Pides pizza para todos y los reconcilias ({n} 💰)? Si los reconcilias, los dos se animan y trabajan más rápido unos días.",
  "staffEvent.quarrel.yes": "Pizza para todos (−{n} 💰)",
  "staffEvent.quarrel.no": "Que lo arreglen solos",
  "staffEvent.idea.text": "“¿Y si ponemos una oferta del día en la entrada con una etiqueta llamativa? ¡La gente va a entrar!” Si apoyas la idea, la tienda ganará popularidad y su autor se animará.",
  "staffEvent.idea.yes": "¡Gran idea!",
  "staffEvent.idea.no": "No hace falta",
  "staffEvent.best.text": "{name} trabajó todo el mes sin un solo error. ¿Le das un bono de {n} 💰 como “empleado del mes”? Se sentirá renovado y con ánimo.",
  "staffEvent.best.yes": "Bono (−{n} 💰)",
  "staffEvent.best.no": "Solo agradecer",
  "upgrade.kitchen": "Cocina",
  "upgrade.kitchen.desc": "Un cuarto encima de la cafetería: ensalada Olivier, borsch, crepes, pelmeni, syrniki y sopa de pescado, en el estante «Comida» de la entrada; los clientes toman una porción camino a la caja. Con cocinero, la cocina compra sus ingredientes y cocina todo el día",
  "tip.rhythm.title": "Caja al ritmo",
  "tip.rhythm.text": "Cuando cobras tú, los productos avanzan por la cinta hacia el escáner. Toca la pantalla cuando el círculo llegue al marco: justo a tiempo es “Perfecto”, y las propinas suben (el doble en la hora pico). Si fallas, el producto pasa otra vez.",
