  "kitchen.noChef": "Sin cocinero, la cocina cocina sola cada mañana con productos de la tienda (almacén y luego estantes), lo que quepa en el estante «Comida». Puedes cocinar más con los botones de abajo. Un cocinero (pestaña «Personal») cocinaría todo el día y compraría los ingredientes.",
