  "tale.title": "{icon} {name} · parte {n} de {of}",
  "tale.need.money": "necesitas {n} 💰",
  "tale.need.product": "necesitas {n} en stock",
  "tale.anya.name": "Anya, la estudiante",
  "tale.anya.0.text": "“¡Hola! Soy Anya, estudio Economía. Mi beca se retrasó… ¿Puedo ayudarte a acomodar los estantes a cambio de un pan?”",
  "tale.anya.0.0": "Claro, llévate el pan",
  "tale.anya.0.1": "Lo siento, hoy no",
  "tale.anya.1.text": "Anya volvió: “¡Aquella vez me salvaste! Se acercan los exámenes y el libro cuesta 300. ¿Me lo prestas? Te lo devuelvo con mi primer sueldo, de verdad.”",
  "tale.anya.1.0": "Toma, 300 💰",
  "tale.anya.1.1": "No puedo, lo siento",
  "tale.anya.2.text": "Anya está radiante: ¡sacó la nota máxima en todos los exámenes! Te devuelve el doble, 600 💰, y trajo a toda su clase: “¡El tendero más amable de la ciudad!”",
  "tale.anya.2.0": "¡Gracias, Anya!",
  "tale.anya.3.text": "Anya pasó a contarte la noticia: ¡aprobó los exámenes! Consiguió el libro en la biblioteca. Trajo a un par de compañeros.",
  "tale.anya.3.0": "¡Me alegro por ti!",
  "tale.anya.4.text": "Anya se graduó y consiguió trabajo en el banco de al lado. “Les hablé de ti a todos mis colegas: ¡ahora solo comprarán el almuerzo aquí!”",
  "tale.anya.4.0": "¡Qué bien!",
  "tale.wedding.name": "Timoféi, el novio",
  "tale.wedding.0.text": "Un joven juguetea nervioso con un estuche de anillo: “Soy Timoféi. ¡Katia y yo nos conocimos en tu fila! Quiero pedirle matrimonio justo en la puerta. ¿Me ayudas a decorar la vitrina? Globos y lucecitas, unas 200.”",
  "tale.wedding.0.0": "¡Hagámoslo! (−200 💰)",
  "tale.wedding.0.1": "Esto es una tienda, no un salón de bodas",
  "tale.wedding.1.text": "¡Katia dijo que sí! Medio barrio aplaudió frente a la vitrina. Timoféi: “La boda es en 5 días. Necesitamos 30 panes para el pan de boda y los sándwiches, ¡pagamos el doble!”",
  "tale.wedding.1.0": "¡Hecho!",
  "tale.wedding.1.1": "No llegamos, lo siento",
  "tale.wedding.2.text": "¡Día de la boda! Timoféi, de traje, vino por el pedido: 30 panes.",
  "tale.wedding.2.0": "¡Aquí tienes tu pedido!",
  "tale.wedding.2.1": "Perdón, no llegamos a tiempo…",
  "tale.wedding.3.text": "Timoféi y Katia volvieron de la luna de miel: “Ahora solo compramos aquí. ¡Y se lo contamos a todos los invitados de la boda!”",
  "tale.wedding.3.0": "¡Felicidades!",
  "tale.busker.name": "Gosha, el músico",
  "tale.busker.0.text": "Un muchacho con guitarra en la puerta: “Soy Gosha. ¿Puedo tocar afuera de tu tienda? La gente estará más contenta y tú tendrás más clientes.”",
  "tale.busker.0.0": "¡Toca!",
  "tale.busker.0.1": "Sin ruido, por favor",
  "tale.busker.1.text": "¡Un video de Gosha cantando en tu puerta llegó al millón de vistas! Un bloguero quiere grabar dentro de la tienda.",
  "tale.busker.1.0": "¡Adelante!",
  "tale.busker.1.1": "No, estorba",
  "tale.busker.2.text": "Gosha formó una banda y te invita a su primer concierto. Necesitan un patrocinador: 1000 💰, y tu tienda saldrá en todos los carteles de la ciudad.",
  "tale.busker.2.0": "Patrocinar (−1000 💰)",
  "tale.busker.2.1": "¡Suerte, Gosha!",
