  "nightGuest.taxi.0": "Turno hasta el amanecer… ¡agua, por favor!",
  "nightGuest.taxi.1": "Cinco minutos de pausa y de vuelta al volante",
  "nightGuest.student.0": "¡Exámenes! Necesito pelmeni y jugo",
  "nightGuest.student.1": "El trabajo final no se va a escribir solo…",
  "nightGuest.doctor.0": "Acabo de salir de guardia. ¿Algo sano?",
  "nightGuest.doctor.1": "24 horas de pie: manzanas y jugo",
  "nightGuest.guard.0": "Ronda nocturna y el estómago vacío",
  "nightGuest.guard.1": "Vigilo el almacén de enfrente. ¿Algo de pan?",
  "nightGuest.musician.0": "¡Terminó el concierto, pero sigo a mil!",
  "nightGuest.musician.1": "¿Te toco algo?",
  "nightGuest.insomniac.0": "No puedo dormir… un poco de leche tibia me ayudaría",
  "nightGuest.insomniac.1": "¡En mis tiempos las tiendas no abrían de noche!",
  "nightGuest.lovers.0": "Flores a las 2 de la mañana, ¿tienen?",
  "nightGuest.lovers.1": "Shh… es una sorpresa para ella",
  "nightGuest.vampire.0": "¿Jugo de tomate? Solo de tomate…",
  "nightGuest.vampire.1": "Qué luces tan brillantes… bueno, no importa",
  "nightStory.studentDebt.title": "🎓 Estudiante sin dinero",
  "nightStory.studentDebt.text": "“Mi beca llega en tres días, pero tengo hambre ahora. ¿Me fías {item}? ¡Te pago el doble, lo prometo!”",
  "nightStory.studentDebt.note": "Normalmente pagan y traen a sus amigos. Aunque no siempre.",
  "nightStory.studentDebt.yes": "Toma, ¡provecho!",
  "nightStory.studentDebt.no": "Lo siento, no fío",
  "nightStory.taxiTea.title": "🚕 Un taxista congelado",
  "nightStory.taxiTea.text": "“¿Puedo calentarme aquí diez minutos? Les hablaré a mis pasajeros de tu tienda: abierta toda la noche y con buen trato.”",
  "nightStory.taxiTea.note": "Mañana, 6% más de clientes.",
  "nightStory.taxiTea.yes": "Claro, caliéntate",
  "nightStory.taxiTea.no": "Esto no es una sala de espera",
  "nightStory.sleepyDoctor.title": "🩺 Una doctora se durmió junto a la caja",
  "nightStory.sleepyDoctor.text": "Una doctora, tras una guardia de 24 horas, se sentó junto a la caja… y se quedó dormida con la canasta en la mano.",
  "nightStory.sleepyDoctor.note": "Ya descansada, comprará mucho y se lo contará a sus colegas.",
  "nightStory.sleepyDoctor.yes": "Que duerma, tráele una manta",
  "nightStory.sleepyDoctor.no": "Despertarla: “¡Aquí no se duerme!”",
  "nightStory.busker.title": "🎸 Un músico en la puerta",
  "nightStory.busker.text": "“¿Puedo tocar en tu puerta hasta que termine el turno? La gente se anima y tú ganas clientes.”",
  "nightStory.busker.note": "30% más de clientes nocturnos y propinas.",
  "nightStory.busker.yes": "¡Toca!",
  "nightStory.busker.no": "No, la gente duerme",
  "nightStory.thanks": "¡Gracias!",
