  "staffTab.reliefOn": "Tu cajero de relevo atiende tu caja todo el día. Toca la caja para que escanee más rápido: tú quedas libre para otras tareas.",
  "drama.teaser": "Sonia quería contarte algo… Vuelve mañana: te esperará.",
  "drama.night.before.1": "Papá, ¿otra vez hasta tarde? Te dejo encendida la luz del pasillo.",
  "drama.night.before.2": "Cuarta noche seguida que ceno sola. Lo digo solo por llevar la cuenta.",
  "drama.night.before.3": "Llevo una semana sin verte por la noche. ¿La tienda se acuerda siquiera de cómo soy?",
  "drama.night.after.1": "Papá, ¿otro turno de noche? Vale. El té está en el termo y el termo en tu bolsa. No te hagas el héroe.",
  "drama.night.after.2": "Cuarta noche seguida. Teníamos un trato: nada de esconderse en el trabajo.",
  "drama.night.after.3": "Papá. Una semana de turnos de noche. Mañana cierras a tu hora, que lo voy a comprobar.",
