  "decor.pack_newyear": "Pack de Año Nuevo",
  "decor.holidayEarn": "🎁 de postales",
  "decor.holidayNote": "Objeto festivo: lo regalan las postales de la fiesta, {when}. No se puede comprar, solo coleccionar.",
  "decor.holidayWhen.newyear": "en diciembre",
  "decor.holidayWhen.feb23": "alrededor del 23 de febrero",
  "decor.holidayWhen.march8": "alrededor del 8 de marzo",
  "decor.packNote": "Solo se vende como “{pack}”: {items}. Se compra una vez y es tuyo para siempre.",
  "live.newyear.card.1": "¡1 de diciembre! La tienda se va vistiendo de fiesta poco a poco. ¡Feliz primer día de invierno!",
  "live.newyear.card.2": "Afuera huele a nieve y adentro, a mandarinas. ¡Que tengas un lindo día!",
  "live.newyear.card.3": "Que hoy la caja suene más seguido y tu corazón siga calientito.",
  "live.newyear.card.4": "Los clientes entran con las mejillas rojas por el frío: sonríele a cada uno.",
  "live.newyear.card.5": "Es hora de colgar la guirnalda y poner a hervir el agua para el té.",
  "live.newyear.card.6": "La nieve cruje bajo los pies: eso es un invierno de verdad. ¡Que tengas un día cálido!",
  "live.newyear.card.7": "¡Ya pasó una semana de diciembre! Gracias por venir todos los días.",
  "live.newyear.card.8": "Pide un pequeño deseo: le da tiempo de cumplirse antes de Año Nuevo.",
  "live.newyear.card.9": "Alguien ya está eligiendo regalos. ¡Ojalá también vengan a tu tienda!",
  "live.newyear.card.10": "Una taza de chocolate y la luz cálida de la vitrina: eso sí es acogedor.",
  "live.newyear.card.11": "¡Que hoy no se venza ni un solo yogur!",
  "live.newyear.card.12": "En las tardes de invierno, la vitrina brilla más que nunca.",
  "live.newyear.card.13": "La abuela dice que en diciembre hasta el pan huele a fiesta.",
  "live.newyear.card.14": "Dibujos de escarcha en el vidrio. Qué bonito, ¿verdad?",
  "live.newyear.card.15": "Ya van dos semanas de diciembre. ¡Gracias por estar aquí!",
  "live.newyear.card.16": "¡A medio camino de Año Nuevo! Aquí tienes un regalito.",
  "live.newyear.card.17": "Que hoy los clientes sean amables y las filas, cortas.",
  "live.newyear.card.18": "Mandarinas, árbol, guirnalda: la fiesta ya toca a la puerta.",
  "live.newyear.card.19": "El gato también espera el Año Nuevo. Sobre todo, el pescado de la cena.",
  "live.newyear.card.20": "Los días de invierno son cortos: que los buenos momentos sean largos.",
  "live.newyear.card.21": "La noche más larga del año. ¡Desde aquí todo se vuelve más luminoso!",
  "live.newyear.card.22": "Tres semanas listas. ¡La fiesta está a la vuelta de la esquina!",
  "live.newyear.card.23": "Que hoy te pase al menos una sorpresa agradable.",
  "live.newyear.card.24": "Los regalos se van juntando bajo el árbol. ¡Y aquí tienes una postal!",
  "live.newyear.card.25": "¡Falta una semana para Año Nuevo! Justo el tiempo de los milagros.",
  "live.newyear.card.26": "Alguien está haciendo un muñeco de nieve en la puerta. ¡El invierno está en su punto!",
  "live.newyear.card.27": "Que en el año nuevo la tienda sea todavía más acogedora.",
  "live.newyear.card.28": "Ya casi. ¡Cuídate en el ajetreo de las fiestas!",
  "live.newyear.card.29": "Ensaladas, mandarinas, guirnaldas… y una pizca de magia.",
  "live.newyear.card.30": "Mañana es el último día del año. ¡Recuerda todo lo que lograste!",
  "live.newyear.card.31": "¡Feliz Año Nuevo! Gracias por pasar diciembre con nosotros. ¡Que sea un año cálido!",
  "live.feb23.card.1": "¡Feliz Día del Defensor de la Patria! Que siempre tengas a alguien que te respalde.",
  "live.feb23.card.2": "¡Salud, tranquilidad y un hombro firme en quien apoyarte!",
  "live.feb23.card.3": "¡Felices fiestas! Que el valor y la bondad vayan siempre de la mano.",
  "live.march8.card.1": "¡La primavera está en la puerta! Que cada día sea cálido y luminoso.",
  "live.march8.card.2": "La mimosa huele a primavera. ¡Que tu ánimo sea igual de soleado!",
  "live.march8.card.3": "¡Feliz Día Internacional de la Mujer! Que te rodeen las flores, las sonrisas y las palabras amables.",
  "ads.guests": "Clientes extra: ≈{n} al día",
  "news.kiosks": "🖥 Autocobro: los clientes con una canasta pequeña escanean sus productos solos. Crecer → Autocobro.",
  "news.relief": "🧑‍💼 El cajero de relevo (desde el local «Tiendita») atiende tu caja todo el día: tú quedas libre para otras tareas. Pestaña Personal.",
  "news.restock": "📦 \"Comprar lo necesario\" ahora es un solo toque: la mercancía va directo a los estantes y al almacén.",
  "news.housewarming": "🏠 Inauguración: después de una mudanza, la primera factura sigue siendo con el alquiler anterior.",
  "news.branch": "🏬 Sucursal: tras vencer a Giant en el nivel Gran almacén, puedes comprar su edificio; tu segunda tienda gana dinero sola cada noche. «Crecer» → «Sucursal».",
  "news.goal": "🎯 Arriba hay una meta principal con barra de progreso: tócala para ver qué hacer. El resumen del día te dice qué viene mañana. Y el menú ya no salta al plegar secciones.",
