  "news.prices": "🏷 Ajustamos precios: más baratos la entrada, el baño, la luz LED, las etiquetas electrónicas y los quioscos; más caros la tarjeta de cliente, las cámaras y la publicidad grande; el turno de noche gana menos. Lo que ya compraste se queda.",
