  "store.l6": "Hipermercado",
  "hyper.title": "Mudanza al hipermercado",
  "hyper.lock.giant": "El edificio del «Giant», al otro lado de la calle, todavía es suyo. Vence al «Giant», abre ahí una sucursal y podrás mudar allí tu tienda principal.",
  "hyper.lock.branch": "Primero abre una sucursal en el edificio del «Giant» (abajo, «Sucursal»); después podrás mudarte allí por completo.",
  "hyper.offer": "Tu tienda principal se muda al edificio del «Giant»: sala grande, {slots} lugares para estantes, almacén para {wh}, clientes ×{g}. Alquiler: {rent} 💰 al mes; la primera factura aún va con el precio anterior.",
  "hyper.branch": "La tienda vieja no cierra: será la sucursal «{name}». El encargado y el equipo pasan allí, todas las mejoras de la sucursal se mantienen y los ingresos siguen igual.",
