  "gift.restart": "Mañana la racha empieza de nuevo: {treat}",
  "gift.treat.1": "empanadas de repollo",
  "gift.treat.2": "bollos de requesón",
  "gift.treat.3": "un frasco de mermelada",
  "gift.treat.4": "un pastel de manzana",
