  "gift.treat.7": "un gran pastel de miel",
  "letter.grandma.1": "Cariño, ¿cómo estás? ¿Comes bien? Te mando un poquito para tus gastos: cómprate un bollito de amapola.",
  "letter.grandma.2": "Anoche me pasé la tarde recordando cómo te escondías detrás del mostrador de pequeño. ¡Y ahora el dueño eres tú! Qué orgullo. Te mando un poquito.",
  "letter.grandma.3": "La vecina del tercer piso elogió tu pan. Dice que es suave, como el de nuestro pueblo. Toma, para la tienda.",
  "letter.grandma.4": "Te escribo a la luz de una vela: otra vez se fue la luz. No subas los precios, que la gente buena no olvida. Aquí tienes un poco, y no discutas.",
  "letter.grandma.5": "Te tejí unos calcetines, te los llevo el fin de semana. Mientras tanto, un dinerito en el sobre, para que la caja suene más alegre.",
  "letter.grandma.6": "Dijeron en la tele que va a llover. ¡Pon paraguas en la entrada! Y aquí tienes algo, por si acaso.",
  "letter.grandma.7": "Tu abuelo decía: “Una tienda se sostiene gracias a los que vienen todos los días”. Tú esfuérzate por ellos, y yo, por ti. Besos.",
  "letter.grandma.8": "¡Las empanadas me salieron mejor que nunca! Lástima que no se puedan mandar por correo. Te mando lo que sí se puede: cómprate algo para el té.",
  "letter.valya.1": "¡Hola, vecino! Vi que anoche tenías la luz encendida hasta tarde. No trabajes de más. Si necesitas algo, toca la pared.",
  "letter.valya.2": "Oí en el mercado que la leche va a subir pronto. Te aviso como vecina, para que lo sepas antes.",
  "letter.valya.3": "A mi gato se le volvió a ir el apetito, ¡pero tu pescado se lo come con ganas! Así que espérame: iré a buscar pescadito.",
  "letter.valya.4": "Ayer tu fila llegaba hasta la esquina. ¡Qué alegría me dio! Aunque un segundo cajero no vendría mal, ¿eh?",
  "letter.valya.5": "Las flores junto a la caja son una maravilla. Le compré unas a mi hermana y todavía cree que son del mercado. ¡No te delato!",
  "letter.valya.6": "Te dejo una nota, que por las mañanas siempre estás ocupado. Gracias por guardarme una barra de pan fresca. Es poca cosa, pero se agradece.",
  "letter.sonya.1": "Papá, dibujé nuestra tienda para mi portafolio de la escuela de arte. El gato quedó más importante que tú. Sin ofender.",
  "letter.sonya.2": "Papá, en ciencias sociales nos dejaron un ensayo sobre pequeños negocios. ¿Te puedo entrevistar? Pero responde en serio.",
  "letter.sonya.3": "Papá, ¿puedo atender la caja el sábado? Cuento más rápido que tú, comprobado.",
  "letter.sonya.4": "Papá, le hice a la tienda una página en redes sociales. Ya tiene cuarenta seguidores. De nada.",
  "letter.sonya.5": "Papá, ¿otra vez llegas tarde? La cena está en el refrigerador, le puse tu nombre, que si no se la come la abuela.",
  "letter.sonya.6": "Papá, en orientación vocacional nos preguntaron qué queremos ser. Dije: todavía no sé, pero seguro que no un adulto aburrido. Tú no cuentas.",
  "letter.regular.1": "Jefe, gracias por {item}: mejor que en el «Giant», palabra. Te escribo para que lo sepas: soy tu cliente.",
  "letter.regular.2": "Pasé ayer, pero estabas ocupado. Quería decirte que en tu tienda uno se siente como en casa. Mañana vuelvo.",
  "letter.regular.3": "Le conté a mi nieto de tu tiendita, y ahora él también quiere ser tendero. ¡Tú sigue así!",
  "letter.regular.4": "Te dejo una nota bajo la puerta: {item} de tu tienda es mi debilidad. Pero no subas el precio, ¿trato hecho?",
  "letter.regular.5": "Fui a ver a mi hermana a otro barrio: allí no hay una tienda como esta. Extrañé tu caja, ¿puedes creerlo?",
  "letter.regular.6": "Gracias por apartarme {item} aquella vez que llegué tarde. Esas cosas no se olvidan.",
  "letter.regular.7": "Jefe, ¡qué luminosa y limpia está ahora tu sala! Da gusto entrar. Saludos a tu abuela.",
  "letter.regular.8": "Te escribo una postal porque sí. Nuestro barrio es bueno mientras tu tienda esté en él.",
