  "hood.bought": "¡El barrio se pone bonito!",
  "hood.boughtText": "«{name}» ya está en la calle. ¡Échale un vistazo también de noche!",
  "hood.lamps": "Farolas nuevas",
  "hood.lamps.desc": "Farolas de hierro fundido de dos brazos a lo largo de la acera de enfrente. Por la noche la calle queda iluminada y acogedora.",
  "hood.beds": "Maceteros con flores",
  "hood.beds.desc": "Maceteros de piedra a lo largo de las aceras: flores en verano, ramas de abeto en invierno.",
  "hood.bikes": "Bicicletero",
  "hood.bikes.desc": "Soportes para bicicletas junto a la entrada: es más fácil pasar en bici.",
  "hood.bus": "Parada techada",
  "hood.bus.desc": "En lugar de un simple poste, una parada con techo de vidrio y un banco. Quien espera el autobús entra a tu tienda.",
  "hood.mural": "Mural",
  "hood.mural.desc": "Unos artistas pintarán la pared junto a la plaza: sol, flores y una abuela con una hogaza. Los habituales están orgullosos del barrio.",
  "hood.benches": "Plaza con bancos",
  "hood.benches.desc": "Una plaza con baldosas, bancos y arbustos al otro lado de la calle: un lugar para sentarse con las compras.",
  "hood.fir": "Abeto en la plaza",
  "hood.fir.desc": "Un gran abeto en la plaza. En invierno lo decoran: adornos, guirnalda y una estrella.",
  "hood.fountain": "Fuente del estanque",
  "hood.fountain.desc": "Una fuente a orillas del estanque del parque: en verano todo el barrio pasea por ahí.",
  "hood.playground": "Área de juegos",
  "hood.playground.desc": "Tobogán, columpios y arenero en el parque. Las familias con niños compran a menudo.",
  "hood.facades": "Fachadas vecinas nuevas",
  "hood.facades.desc": "Jardineras con flores en las ventanas y banderines para las casas vecinas. Una calle de postal.",
  "hood.fair": "Puestos de feria",
  "hood.fair.desc": "Tres puestos alegres en la plaza: miel, manzanas y pasteles. La gente sale a la calle.",
  "hood.statue": "Monumento a la abuela",
  "hood.statue.desc": "Una abuela de bronce con una hogaza en la plaza. «A la fundadora del comercio, de parte de un barrio agradecido».",
  "hood.statue.plaque": "A la abuela",
