  "echo.head": "{icon} Eco: «{title}»",
  "echo.hello": "¿Se acuerda de mí?",
  "echo.later": "🔁 Esta historia volverá…",
  "echo.ok.good": "¡Qué bien!",
  "echo.ok.bad": "Vaya… Lo tendré en cuenta",
  "echo.drop": "clientes −{p}% por {d} d",
  "echo.boostLine": "🔁 Eco: clientes +{p}% {n} d más",
  "echo.dropLine": "🔁 Eco: clientes −{p}% {n} d más",
  "tip.echo.title": "El eco de tus decisiones",
  "tip.echo.text": "Las escenas no se olvidan. En una o dos semanas sus protagonistas volverán, agradecidos u ofendidos: lo que siembras, recoges.",
  "skit.robbery.confess.1": "Devuelve el bolso y vete. Por esta vez te perdono",
  "skit.robbery.forgive": "¡Mi bolso está entero! Bueno… ya que lo confesó, que se vaya. A lo mejor se endereza.",
  "echo.galina": "¡Soy yo, Galina Petrovna, la del bolso! Todo el barrio sabe ya qué clase de dueño es usted. ¡Tome, le hice empanadas!",
  "echo.denis": "¿Recuerdas a Denís, el chico de la sudadera al que dejaste ir? Vino él solo: «Quiero ganarme la vida honradamente. ¿Me contrata de reponedor? No pido mucho».",
  "echo.denis.0": "Contratarlo de reponedor: {n} 💰 al mes (normalmente {full})",
  "echo.denis.1": "Ahora no, pero suerte",
  "echo.denis.2": "No hay plaza: que ayude a arreglar la entrada",
  "echo.wrongCourier": "¿Recuerdas a Ruslán, el repartidor al que llamaste ladrón? No lo ha olvidado: se lo contó a todos los repartidores del barrio, y ahora sus pedidos pasan de largo.",
  "echo.wrongPainter": "¿Recuerdas a Stiopa, el pintor al que acusaste sin razón? Toda su cuadrilla almuerza ahora en otra tienda, y cuenta a todos por qué.",
  "echo.dogClub": "¿Recuerdas a Tioma y a Rosquilla, al que atrajiste con salchichón? La dueña del criadero oyó la historia ¡y trajo a todo su club canino!",
  "echo.bublik": "¡Soy yo, Tioma! ¡Mire cuánto ha crecido Rosquilla! Ahora pasamos por aquí todos los días, y mamá solo compra la leche aquí.",
  "echo.tyomaCold": "¿Recuerdas a Tioma, al que se le escapó el cachorro? No le hiciste caso. Su mamá lo contó en el chat de padres…",
  "echo.sergeant": "¿Recuerda a Víktor y su billete falso? ¡Gracias a él dimos con toda la banda! Aquí tiene un diploma de la comisaría, y una recompensa.",
  "echo.viktor": "¿Recuerdas a Víktor y su billete falso? Lo atraparon en el barrio vecino, y el sargento Kovaliov te devolvió parte del cambio.",
  "echo.bakery": "¿Se acuerda de mis empanadas? ¡Abrí mi propia panadería junto a la parada! La primera tanda es para usted, de regalo. ¡Y les digo a todos dónde empecé!",
  "echo.stale": "¿Recuerdas las empanadas de Liosha? Los vecinos aún bromean: «¿No es ahí donde con las empanadas se podían clavar clavos?»",
  "echo.classTrip": "¡Anna Serguéievna le manda una tarjeta! Y esta semana toda la clase vendrá de excursión, «Cómo funciona una tienda», ¡con los padres!",
  "echo.roses": "¿Recuerdas las rosas para Anna Serguéievna? Estuvo estornudando una semana. En el chat de padres preguntan quién las recomendó, y todos saben quién.",
  "echo.sequel": "¿Se acuerda del directo? ¡Mis seguidores piden más! Hoy grabo «Un día en mi tienda favorita»: ¡espere visitas!",
  "echo.roast": "¿Recuerdas el directo de Karina? Subió un recorte: «El dueño de la tienda insulta a los seguidores». Cien mil visitas y comentarios demoledores…",
  "echo.couriers": "¿Se acuerda del aguacero? Ahora todo nuestro turno almuerza aquí, llueva o haga calor. ¡Tome, esto es de los chicos!",
  "echo.scarf": "Ruslán trajo un paquete: la abuela del quinto piso, a la que llevaste las medicinas bajo la lluvia, ¡te tejió una bufanda! Y habla de ti a todas sus vecinas.",
  "echo.dispatcher": "¿Recuerdas el aguacero y las medicinas que llegaron tarde? Oleg, el de la central, ahora manda a los repartidores a comer a otros sitios.",
  "echo.fired": "¿Recuerdas a Ruslán? Después de aquel aguacero lo despidieron. Ahora entra sin su mochila, y sin su sonrisa.",
  "col.hint.friendDay": "viene desde el día {day}",
  "col.hint.cat": "quédate con el gato que llegue a la tienda",
  "col.hint.bobik": "adopta al perro Bobik para la guardia nocturna",
  "col.hint.shops": "amplía la tienda en la pestaña “Crecer”",
  "col.hint.shopCost": "mudanza por {cost} 💰 en la pestaña “Crecer”",
  "col.hint.hyper": "múdate al edificio del «Giant» cuando ya tengas allí una sucursal",
