  "career.rank.admin": "encargado de sala",
  "career.best.title": "🏅 ¡Empleado del mes!",
  "career.best.text": "El mejor de las últimas cuatro semanas — por trabajo real, no por sorteo. Su nombre ya está en el cuadro de honor de la sala.",
  "career.best.stats": "Turnos: {shifts}",
  "career.best.say": "«¡Ay, gracias! ¡Me esforzaré todavía más!»",
  "career.best.ask": "¿Cómo lo premiamos?",
  "career.best.cash": "💰 Bono {n}",
  "career.best.gift": "🎁 Un regalo de {n}",
  "career.best.hint": "Un premio motiva: unos días de trabajo más rápido y ni piensa en irse.",
  "career.promo.senior": "Un sénior trabaja un poco más rápido y enseña a los demás — ellos ganan experiencia más rápido.",
  "career.promo.admin": "Un encargado de sala es aún más rápido y pone orden — toda la sala trabaja un poco más ágil.",
  "career.promo.noHint": "Sin rencores: volverá a pedirlo en un par de semanas.",
  "career.branch.title": "🏬 Uno de los nuestros en la sucursal",
  "career.branch.text": "«Conozco la tienda como la palma de mi mano. ¿Y si dirijo yo la sucursal?»",
  "career.branch.note": "Dejará la sala (queda un puesto libre, puedes contratar a alguien nuevo), y con uno de los nuestros al mando la sucursal gana un {p}% más.",
  "career.branch.yes": "Nombrar gerente",
  "career.branch.no": "Lo necesito aquí",
  "career.left.title": "👋 {name} se va",
  "career.leave.1": "«Voy a abrir mi propia panadería pequeña. Aquí lo aprendí todo — ¡gracias!»",
  "career.leave.2": "«Vuelvo a estudiar — era mi sueño desde hace años. ¡Pasaré a saludar!»",
  "career.leave.3": "«Me mudo con mi familia a otra ciudad. Echaré de menos nuestra tienda.»",
  "career.leave.4": "«Toca un merecido descanso. Tantos años detrás del mostrador — ¡ahora les toca a los nietos!»",
  "career.left.note": "Turnos en la tienda: {days}. Nos despedimos en buenos términos — sin deudas ni rencores, y promete escribir.",
