  "lottery.title": "Lotería",
  "lottery.stand": "Puesto de billetes",
  "lottery.note": "Un puesto de billetes junto a la caja: en la cola la gente compra billetes y a ti te quedan {n} 💰 de cada uno. No hay que comprar nada.",
