  "lottery.win.text": "¡En el sorteo de anoche ganó a lo grande un billete comprado aquí! La lotería envió a la tienda un premio de {bonus} 💰. En el barrio dicen que esta es la tienda de la suerte: hasta el día {until}, un {p}% más de clientes.",
