  "tip.lottery.title": "Lotería en la caja",
  "tip.lottery.text": "Los clientes de la cola compran billetes y te queda una pequeña parte de cada uno. De vez en cuando nuestro billete gana a lo grande: un premio y unos días con más clientes. Y a veces la ciudad prohíbe las loterías por un tiempo.",
  "review.lottery.0": "Compré un billete y otra vez nada. La tienda no tiene la culpa, pero duele.",
  "review.lottery.1": "Los billetes junto a la caja tientan mucho. ¡Y siempre gana otro!",
