  "staffStats.quirk": "💬 {text}",
  "staffStats.quirk.0": "Conoce por su nombre a todos los habituales",
  "staffStats.quirk.1": "Tararea con la radio cuando cree que nadie escucha",
  "staffStats.quirk.2": "Solo bebe té en su taza con un gatito",
  "staffStats.quirk.3": "Pone cada etiqueta mirando al frente",
  "staffStats.quirk.4": "Llega diez minutos antes del turno",
  "staffStats.quirk.5": "En la comida da de comer a las palomas de la entrada",
  "staffStats.quirk.6": "Se sabe de memoria el precio de todo",
