  "staffStats.quirk.8": "Es hincha del equipo de fútbol del barrio",
  "staffStats.quirk.9": "Ahorra para una bicicleta",
  "staffStats.quirk.10": "Trae galletas caseras para el equipo",
  "staffStats.quirk.11": "Cuenta sus pasos y presume de récords",
  "summary.staffRecord": "🏆 Récord de turno",
  "summary.staffRecordValue": "{name} — {what}: {n}",
  "career.head": "💼 La sucursal la dirige {name} (desde el día {day}): ingresos +{p}%",
  "career.nextBest": "🏅 Empleado del mes — en {n} d.",
  "letter.staff.1": "¡La panadería ya abrió! Pequeña por ahora, tres mesas. Horneo y me acuerdo de cuando descargábamos camiones antes del amanecer. Pasa — invito yo. ¡Gracias por todo en nuestra tienda!",
  "letter.staff.2": "¡Estoy estudiando! Es difícil, pero me encanta. Les cuento a mis compañeros de nuestra tienda — no se creen que una tienda pueda ser tan acogedora. Gracias por dejarme ir.",
  "letter.staff.3": "Ya nos instalamos. Aquí hay una tienda, pero no es lo mismo — ni gato ni las empanadas de la abuela. Saluda a todos y ráscale al gato detrás de la oreja.",
  "letter.staff.4": "Descansando, plantando tomates. Les cuento a los nietos de nuestra tienda — ¡imagínense, tantos turnos! Si algún día hay mucho lío, llámame y les enseño cómo se hace.",
  // Своя марка на полках (game/lines.ts) и обрыв связи при подкачке (platform/lazy.ts).
  "lazy.offTitle": "Se perdió la conexión",
  "lazy.offText": "Una parte del juego no cargó — reiniciamos, tu progreso está guardado.",
  "product.jam": "Mermelada de la abuela",
  "product.pickles": "Encurtidos caseros",
