  "lines.jam": "Mermelada de la abuela",
  "lines.pickles": "Encurtidos",
  "lines.pelmeni": "Pelmeni hechos a mano",
  "lines.kvass": "Kvas de barril",
  "lines.jam.desc": "La vecina la cocina por las tardes con las manzanas del almacén — incluso las que están a punto de estropearse.",
  "lines.pickles.desc": "Pepinos y tomates del granjero, nuestra propia salmuera. En otoño es la cosecha: más y más barato; en invierno se venden mejor.",
  "lines.pelmeni.desc": "El cocinero los hace después del turno con la carne del almacén. Solo los días que trabajó el cocinero.",
  "lines.kvass.desc": "Kvas del pan de ayer — en primavera y verano, un barril amarillo junto a la puerta. En verano se vende como pan caliente.",
  "lines.title": "Marca propia en los estantes",
  "lines.note": "Se hace de noche después de cerrar — por la mañana los frascos ya están en los estantes. Los proveedores no los tienen: la gente compra tus productos con más ganas y paga más. Cada nivel da más existencias y más demanda.",
