  // Питомцы за звёзды (game/pets.ts, ui/pets.ts, scenes/starPets.ts).
  "pets.title": "Mascotas",
  "pets.note": "Solo por cariño: las mascotas no traen dinero ni clientes, simplemente viven en tu tienda. Una a la vez; puedes llamar a otra cuando quieras.",
  "pets.here": "en la tienda",
  "pets.rename": "Nombre",
  "pets.away": "A casa",
  "pets.call": "Llamar",
  "pets.cosmetic": "Solo decorativa: no cambia ventas ni clientes. Tuya para siempre, incluso tras “Empezar de nuevo”.",
  "pets.welcome": "¡Ya está en casa! ¿Qué nombre le ponemos?",
  "pets.nameAsk": "Nombre de la mascota",
  "pets.nameOk": "Listo",
  "pets.tap": "{name} ❤",
  "pets.record": "¡{name} celebra el récord! 🎉",
  "pets.parrot.words": "¡Hola!,¡Compra pan!,¡Caja!,¡Hurra!,¡Bien hecho!,¡Gracias!,¡Oferta!",
  "pets.parrot.title": "Loro",
  "pets.parrot.name": "Paco",
  "pets.parrot.about": "Un charlatán en su percha junto a las cajas: suelta una palabra de vez en cuando.",
  "pets.parrot.life": "Saluda por la mañana, aletea en un día récord y de noche esconde la cabeza en las plumas.",
  "pets.greet.parrot": "{name}: “¡Ho-la! ¡A-bier-to!”",
  "pets.hamster.title": "Hámster",
  "pets.hamster.name": "Copito",
  "pets.hamster.about": "Una jaula con rueda junto a las cajas: corre sin parar mientras la tienda está abierta.",
  "pets.hamster.life": "Descansa con una pipa, celebra los récords y de noche duerme hecho una bolita.",
  "pets.greet.hamster": "¡{name} ya está dando vueltas a la rueda!",
  "pets.turtle.title": "Tortuga",
  "pets.turtle.name": "Manuelita",
  "pets.turtle.about": "Una vecina sin prisas junto a la pared. En el turno de noche pasea despacito por la tienda.",
  "pets.turtle.life": "Saca la cabeza para darte los buenos días y duerme en su caparazón con la tienda cerrada.",
  "pets.greet.turtle": "{name} asiente despacio: buenos días",
  "pets.bunny.title": "Conejita",
  "pets.bunny.name": "Botón",
  "pets.bunny.about": "Una peludita en su alfombra de paja en el rincón: mueve la nariz y da saltitos.",
  "pets.bunny.life": "Saluda con un salto, brinca de alegría con un récord y de noche duerme como un panecillo.",
  "pets.greet.bunny": "{name} da un salto: ¡buenos días!",
  "pets.corgi.title": "Corgi",
  "pets.corgi.name": "Galleta",
  "pets.corgi.about": "Dormita en su cojín junto a la entrada y mueve el culito a cada cliente.",
  "pets.corgi.life": "Te recibe por la mañana, mueve la cola sin parar en un día récord y de noche duerme profundo.",
  "pets.greet.corgi": "{name} mueve la cola: ¡llegaste!",
  "pets.raccoon.title": "Mapache",
  "pets.raccoon.name": "Pillo",
  "pets.raccoon.about": "Vive junto a la puerta del almacén: se asoma y se esconde. De noche no se esconde nunca.",
  "pets.raccoon.life": "Saluda con la patita por la mañana y con un récord; con la tienda cerrada duerme en una caja.",
  "pets.greet.raccoon": "{name} saluda con la patita desde la puerta",
