  "tenant.title": "Inquilinos",
  "tenant.note": "Puedes alquilar las salas libres del anexo. Pagas la reforma una vez y luego el inquilino funciona solo: cada tarde paga el alquiler y sus visitantes pasan también por la tienda. A veces pide algo de tu almacén: mira el tablón «Pedidos».",
