  "tenant.toys.name": "Máquina de peluches",
  "tenant.toys.desc": "Una máquina de peluches y chicles de bola. Funciona sola: los niños arrastran aquí a sus padres.",
  "garden.title": "El huerto de la abuela",
  "garden.note": "El huerto con el invernadero está a la izquierda de la tienda, detrás del almacén: el botón 🌱 de la tienda lo muestra. La cosecha crece sola, incluso cuando no estás. Al madurar, la abuela la lleva directo al puesto de verduras.",
  "garden.build": "Montar el invernadero · {n}",
  "garden.built": "El invernadero está listo",
  "garden.builtText": "El huerto está a la izquierda de la tienda, detrás del almacén. Los plantones ya están: vuelve en unas horas",
